const $=id=>document.getElementById(id),viewport=$('bodyViewport');let renderer,scene,camera,controls,model,metadata,page=0,dissect=false,loading=false,activePreset='overview';const pageSize=50,completedChunks=new Set(),hideHistory=[],ray=new T.Raycaster(),pointer=new T.Vector2(),temp=new T.Vector3();let previousCamera=new T.Vector3();const linkParams=new URLSearchParams(location.search),linkedPart=linkParams.get('part');let linkApplied=false,questionContext=null;
function read(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}
