async function loadData(){if(loading||!metadata)return;loading=true;$('loadError').hidden=true;$('retryBody').disabled=true;const queue=metadata.chunks.map((_,i)=>i).filter(i=>!completedChunks.has(i)).sort((a,b)=>(a===model.byId.get(linkedPart)?.chunk?-1:0)-(b===model.byId.get(linkedPart)?.chunk?-1:0));let cursor=0,errors=[];await Promise.all(Array.from({length:3},async()=>{while(cursor<queue.length){const i=queue[cursor++];try{const response=await fetch(metadata.chunks[i].gzip);if(!response.ok)throw Error('Model file unavailable');const compressed=new Uint8Array(await response.arrayBuffer());const raw=compressed[0]===31&&compressed[1]===139?gunzipSync(compressed):compressed;if(raw.byteLength!==metadata.chunks[i].bytes)throw Error('Model file has an unexpected length');const buffer=raw.buffer.slice(raw.byteOffset,raw.byteOffset+raw.byteLength);model.addChunk(i,buffer);completedChunks.add(i);if(linkedPart&&!linkApplied&&model.loaded.has(linkedPart)){linkApplied=true;model.enabled=new Set([model.byId.get(linkedPart).system]);model.isolated=true;select(linkedPart,true);}$('bodyProgress').value=model.loaded.size;$('loadingDetail').textContent=`${model.loaded.size.toLocaleString()} / ${totalText} parts loaded`;$('loadStatus').textContent=`Loading ${model.loaded.size.toLocaleString()} / ${totalText}`;
 if(model.loaded.size>100)$('bodyLoading').hidden=true;refreshCounts();renderList();if(model.selected)renderInfo();await new Promise(r=>requestAnimationFrame(r));}catch(e){errors.push(i);console.error('Anatomy chunk',i,e)}}}));loading=false;$('retryBody').disabled=false;if(errors.length){$('bodyLoading').hidden=true;$('loadError').hidden=false;$('loadError').querySelector('span').textContent=`${errors.length} model files could not load. ${model.loaded.size.toLocaleString()} parts are available; retry to load the remainder.`;$('loadStatus').textContent='Some model files need retrying';}else{$('bodyLoading').hidden=true;$('loadStatus').textContent=`${totalText} / ${totalText} PARTS READY`;}refreshCounts();renderList()}
function filtered(){if(!model)return[];let list=searchParts(metadata.parts,$('bodySearch').value,$('searchSystem').value,systems);if($('visibleOnly').checked)list=list.filter(p=>model.visible(p));return list}
function renderList(){if(!model)return;const list=filtered(),pages=Math.max(1,Math.ceil(list.length/pageSize));page=Math.min(page,pages-1);$('searchCount').textContent=`${list.length.toLocaleString()} matches`;$('pageCount').textContent=`${page+1} / ${pages}`;$('pagePrev').disabled=page===0;$('pageNext').disabled=page===pages-1;$('bodyList').replaceChildren();if(!list.length){const p=document.createElement('p');p.className='small';p.textContent='No parts match these filters. Try another name or choose All groups.';$('bodyList').append(p);return}for(const p of list.slice(page*pageSize,(page+1)*pageSize)){const b=document.createElement('button');b.className='body-part'+(p.id===model.selected?' active':'');b.setAttribute('aria-pressed',String(p.id===model.selected));const dot=document.createElement('i');dot.style.background=systems[p.system].color;const label=document.createElement('span');label.textContent=p.name;const sub=document.createElement('small');sub.textContent=p.id+' · '+systems[p.system].name;label.append(sub);const eye=document.createElement('span');eye.className='eye';eye.textContent=!model.loaded.has(p.id)?'…':model.visible(p)?'●':'○';eye.title=!model.loaded.has(p.id)?'Loading':model.visible(p)?'Visible':'Hidden';b.append(dot,label,eye);b.onclick=()=>select(p.id,true);$('bodyList').append(b)}}
function renderSystems(){if(!model)return;$('systemsList').replaceChildren();for(const [key,s] of Object.entries(systems)){const count=metadata.parts.filter(p=>p.system===key).length;const row=document.createElement('div');row.className='system-row';const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=model.enabled.has(key);check.onchange=()=>{check.checked?model.enabled.add(key):model.enabled.delete(key);model.isolated=false;clearPreset();model.update();refreshCounts();renderList();renderInfo()};const countSpan=document.createElement('span');countSpan.className='system-count';countSpan.textContent=count;label.append(check,document.createTextNode(s.name),countSpan);const opacityRow=document.createElement('div');opacityRow.className='opacity-row';const range=document.createElement('input');range.type='range';range.min=5;range.max=100;range.value=Math.round(model.opacity[key]*100);range.setAttribute('aria-label',s.name+' opacity');const output=document.createElement('output');output.textContent=range.value+'%';range.oninput=()=>{model.opacity[key]=+range.value/100;output.textContent=range.value+'%';model.update()};opacityRow.append(range,output);row.append(label,opacityRow);$('systemsList').append(row)}}
