function refreshCounts(){if(!model)return;$('visibleCount').textContent=`${model.countVisible().toLocaleString()} visible · ${model.hidden.size} manually hidden`;$('undoHide').disabled=!hideHistory.length;$('restore').disabled=!model.hidden.size;$('exploredCount').textContent=`${explored.size.toLocaleString()} parts explored`}
