function renderInfo(){if(!model?.selected)return;const p=model.byId.get(model.selected),s=systems[p.system];$('bodyCategory').textContent=s.name.toUpperCase();$('bodyName').textContent=p.name;$('bodyIntro').hidden=true;$('partInfo').hidden=false;$('bodyId').textContent=`${p.id}${p.conceptId?' · '+p.conceptId:''}`;$('bodyEnglish').textContent=questionContext&&questionContext.url.includes('part='+encodeURIComponent(p.id))?questionContext.answer+' '+questionContext.explanation:s.en;$('infoHeading').textContent=questionContext&&p.id===linkedPart?'QUESTION EXPLANATION':'GROUP OVERVIEW';$('infoScope').textContent=questionContext&&p.id===linkedPart?questionContext.modelNote:'This explanation describes the group, not every individual structure.';$('bodyHaTitle').textContent=s.ha;$('bodyHausa').textContent=s.text;$('bodyPin').textContent=p.name;$('partState').textContent=!model.loaded.has(p.id)?'This part is loading':model.visible(p)?'Visible in the model':'Currently hidden';$('isolatePart').setAttribute('aria-pressed',String(model.isolated));$('isolatePart').textContent=model.isolated?'Return to surrounding anatomy':'Isolate this part';$('hidePart').disabled=model.hidden.has(p.id);}
