async function initData(){try{const r=await fetch(indexPath);if(!r.ok)throw Error('Anatomy index unavailable');metadata=await r.json();if(metadata.parts.length!==total||new Set(metadata.parts.map(p=>p.id)).size!==total)throw Error('Unexpected model inventory');model=new BodyModel(metadata,female?femaleConfig:{});scene.add(model.root);explored=new Set([...explored].filter(id=>model.byId.has(id)));$('searchSystem').replaceChildren(new Option('All groups','all'));for(const [key,s] of Object.entries(systems))$('searchSystem').add(new Option(s.name,key));renderSystems();renderList();await loadData()}catch(e){console.error(e);$('bodyLoading').hidden=true;$('loadError').hidden=false;$('loadError').querySelector('span').textContent='The anatomy index could not load. Retry to continue.';$('loadStatus').textContent='Model not loaded'}}
try{setup();bind();$('bodyLang').value=read(storagePrefix+'-language','both');$('bodyLang').onchange();initData()}catch(e){console.error(e);$('bodyLoading').replaceChildren(document.createTextNode('Your browser could not start 3D graphics. Enable hardware acceleration or try a browser with WebGL2 support. The heart lesson is linked above.'))}

